from django.contrib import admin
from django.contrib.auth.admin import UserAdmin as BaseUserAdmin
from django.contrib.auth.models import User, Group
from profile_user.models import UserProfile


# ── Remove built-in Groups from admin (we use UserProfile.role instead) ──
try:
    admin.site.unregister(Group)
except admin.sites.NotRegistered:
    pass


# ── Inline profile inside the User admin ──
class UserProfileInline(admin.StackedInline):
    model = UserProfile
    can_delete = False
    verbose_name_plural = "Profile & Role"
    fields = ('role', 'image')
    extra = 0


class CustomUserAdmin(BaseUserAdmin):
    inlines = (UserProfileInline,)
    list_display = ('username', 'email', 'get_role', 'is_active', 'date_joined')
    list_filter = ('is_active', 'profile__role')

    @admin.display(description='Role')
    def get_role(self, obj):
        try:
            return obj.profile.get_role_display()
        except Exception:
            return '—'


admin.site.unregister(User)
admin.site.register(User, CustomUserAdmin)

{% extends 'base.html' %}

{% block title %}Create News Article{% endblock %}

{% block content %}
<style>
    textarea.form-control {
        resize: none;
    }
</style>
<div class="container" style="max-width: 900px; margin: 0 auto;">
    <h2 class="mb-4 mt-3">Create News Article</h2>
    <form method="post" enctype="multipart/form-data">
        {% csrf_token %}
        {{ form.non_field_errors }}
        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    {{ form.title.label_tag }}
                    {{ form.title }}
                    {{ form.title.errors }}
                </div>
                <div class="mb-3">
                    {{ form.description.label_tag }}
                    {{ form.description }}
                    {{ form.description.errors }}
                </div>
            </div>
            <div class="col-md-6">
                <div class="mb-3">
                    {{ form.content.label_tag }}
                    {{ form.content }}
                    {{ form.content.errors }}
                </div>
                <div class="mb-3">
                    {{ form.image_link.label_tag }}
                    {{ form.image_link }}
                    {{ form.image_link.errors }}
                </div>
                <div class="mb-3">
                    {{ form.author.label_tag }}
                    {{ form.author }}
                    {{ form.author.errors }}
                </div>
            </div>
        </div>
        <button type="submit" class="btn btn-primary">Submit</button>
    </form>
</div>
{% endblock %}

