from django.contrib.auth import authenticate, login, logout
from django.contrib.auth.models import User
from django.shortcuts import render, redirect

from account.forms import RegisterForm, LoginForm


def register_view(request):
    if request.method == "POST":
        form = RegisterForm(request.POST)
        if form.is_valid():
            User.objects.create_user(
                username=form.cleaned_data["username"],
                email=form.cleaned_data["email"],
                password=form.cleaned_data["password"]
            )
            request.session["registered_user"] = form.cleaned_data["username"]
            return redirect("account:register_success")
    else:
        form = RegisterForm()
    return render(request, "account/register.html", {"form": form})

def register_success_view(request):
    return render(request, "account/register_success.html", {
        "username": request.session.get('registered_user', "New User")
    })

def login_view(request):
    next_url = request.GET.get('next') or request.POST.get('next')
    if request.method == "POST":
        form = LoginForm(request.POST)
        if form.is_valid():
            user = authenticate(
                request,
                username=form.cleaned_data["username"],
                password=form.cleaned_data["password"]
            )
            if user is not None:
                login(request, user)
                if next_url:
                    return redirect(next_url)
                return redirect("profile:profile")
            form.add_error(None, "Incorrect username or password")
    else:
        form = LoginForm()
    return render(request, "account/login.html", {"form": form, "next": next_url})

def logout_view(request):
    from django.contrib.auth import logout as auth_logout
    auth_logout(request)
    return redirect("account:login")

from django.contrib.auth import authenticate, login, logout
from django.contrib.auth.models import User
from django.contrib.auth.decorators import login_required
from django.shortcuts import render, redirect, get_object_or_404

from account.forms import RegisterForm, LoginForm
from profile_user.models import UserProfile


def _get_role(user):
    try:
        return user.profile.role
    except Exception:
        return 'user'


def super_admin_required(view_func):
    """Decorator – only super_admin can access."""
    from functools import wraps
    @wraps(view_func)
    def _wrapped(request, *args, **kwargs):
        if not request.user.is_authenticated or _get_role(request.user) != 'super_admin':
            return redirect('main:main')
        return view_func(request, *args, **kwargs)
    return _wrapped


def admin_or_super_required(view_func):
    """Decorator – admin or super_admin can access."""
    from functools import wraps
    @wraps(view_func)
    def _wrapped(request, *args, **kwargs):
        if not request.user.is_authenticated or _get_role(request.user) not in ('super_admin', 'admin'):
            return redirect('main:main')
        return view_func(request, *args, **kwargs)
    return _wrapped


def register_view(request):
    if request.method == "POST":
        form = RegisterForm(request.POST)
        if form.is_valid():
            User.objects.create_user(
                username=form.cleaned_data["username"],
